export const REFUND_PROOF_SCHEMA='stellar-forge.sf86.refund-reconciliation.v1';
const SHA=/^[a-f0-9]{64}$/;
const UUID=/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/;
